import sys, random
sys.path.insert(0, "/private/tmp/tmpmyh41umx/pete/projects/minisql")
from minisql import values

random.seed(1)
bad = []
for _ in range(20000):
    kind = random.choice(["float", "int"])
    if kind == "float":
        x = random.uniform(-1e12, 1e12) * (10 ** random.randint(-20, 20))
    else:
        x = random.randint(-10**30, 10**30)
    n = random.randint(-10, 12)
    try:
        got = values.call_scalar("ROUND", [x, n])
    except Exception as e:
        bad.append(("ERR", x, n, type(e).__name__, str(e)))
        continue
    if not isinstance(got, float):
        bad.append(("TYPE", x, n, type(got).__name__, got))
print("bad count", len(bad))
for b in bad[:20]:
    print(b)

